import {
  RadioGroup as AriaRadioGroup,
  RadioButton,
  RadioField,
  Label,
  Text,
  FieldError,
} from "react-aria-components";
import type {
  RadioGroupProps as AriaRadioGroupProps,
  RadioFieldProps as AriaRadioFieldProps,
  ValidationResult,
} from "react-aria-components";
import { createContext, useContext } from "react";
import type { ReactNode, Ref } from "react";
import "./RadioGroup.css";

type RadioGroupOrientation = "vertical" | "horizontal";
export type RadioGroupSize = "small" | "medium" | "large";
export type RadioGroupVariant = "standard" | "filled";

// The group's `size`, relayed to each Radio (the SegmentedControl idiom): a Radio lives only in a
// RadioGroup, so it takes no size of its own.
const RadioSizeContext = createContext<RadioGroupSize>("medium");
// The group's `variant`, relayed the same way.
const RadioVariantContext = createContext<RadioGroupVariant>("standard");

export interface RadioGroupProps
  extends Omit<AriaRadioGroupProps, "className" | "children" | "orientation"> {
  /**
   * How each option draws its row. `standard`: the indicator and its label on the page, the options
   * flush. `filled`: every option is a box on the neutral fill, parted from the next, and the chosen
   * one takes the selection fill and a brand edge, for a short set of named choices that each set a
   * value (a filter sheet's presets). The indicator stays in both, so the choice is never colour alone.
   *
   * @default "standard"
   */
  variant?: RadioGroupVariant;
  /**
   * Size axis for the group's own text and every radio in it.
   *
   * @default "medium"
   */
  size?: RadioGroupSize;
  /**
   * Visual item direction, a visual axis beside `variant` and `size` (contract §5).
   *
   * Inherited from React Aria, but **redeclared** on purpose: it is a design-surface prop (it
   * swaps the item row's `flex-direction` and is projected as the Figma `orientation` variant
   * axis), and an inherited prop never reaches `designSurface`, so the axis would have no code
   * anchor. Passed straight through to React Aria as well — `useRadioGroup` turns it into
   * `aria-orientation` + arrow-key direction, so it is behaviour, not only look.
   *
   * @default "vertical"
   */
  orientation?: RadioGroupOrientation;
  /** Group label. */
  label?: string;
  /**
   * A `ContextualHelp` shown after the label, for a note the reader opens when they need it rather
   * than a `description` that is always on screen.
   */
  contextualHelp?: ReactNode;
  /** Supporting description. */
  description?: string;
  /** Validation-failure message (shown in the isInvalid state). */
  errorMessage?: string | ((v: ValidationResult) => string);
  /** Radio list. */
  children?: ReactNode;
  /** Additional class (optional). sd-radio-group is always preserved. */
  className?: string;
  /** Forwarded to the underlying <div> DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export interface RadioProps extends Omit<AriaRadioFieldProps, "className" | "children"> {
  /** Radio label content. */
  children?: ReactNode;
  /** Additional class (optional). sd-radio-group__radio is always preserved. */
  className?: string;
  /** Forwarded to the underlying wrapper <div> DOM node (the input uses inputRef). */
  ref?: Ref<HTMLDivElement>;
}

export function RadioGroup({
  variant = "standard",
  size = "medium",
  orientation = "vertical",
  label,
  contextualHelp,
  description,
  errorMessage,
  children,
  className,
  ...props
}: RadioGroupProps) {
  return (
    <AriaRadioGroup
      {...props}
      orientation={orientation}
      className={className ? `sd-radio-group ${className}` : "sd-radio-group"}
    >
      {contextualHelp ? (
        <div className="sd-radio-group__label-group">
          {label && <Label className={`sd-radio-group__label sd-type-label-${size}`}>{label}</Label>}
          {contextualHelp}
        </div>
      ) : (
        label && <Label className={`sd-radio-group__label sd-type-label-${size}`}>{label}</Label>
      )}
      <div className="sd-radio-group__items" data-orientation={orientation} data-variant={variant}>
        <RadioSizeContext.Provider value={size}>
          <RadioVariantContext.Provider value={variant}>{children}</RadioVariantContext.Provider>
        </RadioSizeContext.Provider>
      </div>
      {description && (
        <Text
          slot="description"
          className={`sd-radio-group__description sd-type-caption-${size}`}
        >
          {description}
        </Text>
      )}
      <FieldError className={`sd-radio-group__error sd-type-caption-${size}`}>
        {errorMessage}
      </FieldError>
    </AriaRadioGroup>
  );
}

// Category A — RadioField (<div>, carries the item value + validation state, provides the
// context RadioButton needs) wraps RadioButton (<label>, the clickable indicator + label).
// Supersedes the deprecated single <Radio>.
export function Radio({ children, className, ...props }: RadioProps) {
  const size = useContext(RadioSizeContext);
  const variant = useContext(RadioVariantContext);
  return (
    <RadioField
      {...props}
      data-size={size}
      data-variant={variant}
      className={
        className ? `sd-radio-group__radio ${className}` : "sd-radio-group__radio"
      }
    >
      {/* The label's type role sits on the <label> itself, so the indicator reads the label's own
          line box (`1lh`) to centre on its first line, as Checkbox's box does. */}
      <RadioButton data-variant={variant} className={`sd-radio-group__radio-button sd-type-body-${size}`}>
        <span aria-hidden="true" className="sd-radio-group__radio-indicator" />
        <span className="sd-radio-group__radio-label">
          {children}
        </span>
      </RadioButton>
    </RadioField>
  );
}

.sd-radio-group {
  display: flex;
  flex-direction: column;
  gap: var(--sd-radio-group-gap);
}
/* Options in a row are parted inline, so the label takes the field-label step above them. */
.sd-radio-group[data-orientation="horizontal"] {
  gap: var(--sd-radio-group-gap-horizontal);
}

/* label-group — present only with `contextualHelp`: the label and its help trigger share one row. */
.sd-radio-group__label-group {
  display: flex;
  align-items: center;
  gap: var(--sd-radio-group-label-group-gap);
}

.sd-radio-group__label {
  padding-inline: var(--sd-radio-group-text-padding-inline);
  color: var(--sd-radio-group-label-foreground);
}

.sd-radio-group__items {
  display: flex;
  gap: var(--sd-radio-group-items-gap);
}
.sd-radio-group__items[data-orientation="vertical"] {
  flex-direction: column;
}
.sd-radio-group__items[data-orientation="horizontal"] {
  flex-direction: row;
  flex-wrap: wrap;
  column-gap: var(--sd-radio-group-items-gap-horizontal);
  row-gap: var(--sd-radio-group-items-row-gap-horizontal);
}
.sd-radio-group__items[data-variant="filled"] {
  gap: var(--sd-radio-group-items-gap-filled);
}

.sd-radio-group__description {
  padding-inline: var(--sd-radio-group-text-padding-inline);
  color: var(--sd-radio-group-description-foreground);
}
.sd-radio-group__error {
  padding-inline: var(--sd-radio-group-text-padding-inline);
  color: var(--sd-radio-group-error-foreground);
}

/* RadioField wrapper (<div>) per item — a tight flex item (no per-item description/error;
   validation/help lives on the RadioGroup). Disabled dims here (RAC emits it on the field). */
.sd-radio-group__radio {
  display: inline-flex;
}
/* filled: the option's box spans its column, so every box in a vertical set is one width. */
.sd-radio-group__radio[data-variant="filled"] {
  display: flex;
}
.sd-radio-group__radio[data-disabled] {
  opacity: var(--sd-state-disabled);
}

/* size — relayed from the Radio's root as `-current` intermediates (contract §6 rule 5), as
   Checkbox does. Medium is the old single set. */
.sd-radio-group__radio[data-size="small"] {
  --sd-radio-group-radio-gap-current: var(--sd-radio-group-radio-gap-small);
  --sd-radio-group-radio-padding-block-current: var(--sd-radio-group-radio-padding-block-small);
  --sd-radio-group-radio-state-layer-spread-current: var(--sd-radio-group-radio-state-layer-spread-small);
  --sd-radio-group-radio-indicator-size-current: var(--sd-radio-group-radio-indicator-size-small);
  --sd-radio-group-radio-dot-size-current: var(--sd-radio-group-radio-dot-size-small);
}
.sd-radio-group__radio[data-size="medium"] {
  --sd-radio-group-radio-gap-current: var(--sd-radio-group-radio-gap-medium);
  --sd-radio-group-radio-padding-block-current: var(--sd-radio-group-radio-padding-block-medium);
  --sd-radio-group-radio-state-layer-spread-current: var(--sd-radio-group-radio-state-layer-spread-medium);
  --sd-radio-group-radio-indicator-size-current: var(--sd-radio-group-radio-indicator-size-medium);
  --sd-radio-group-radio-dot-size-current: var(--sd-radio-group-radio-dot-size-medium);
}
.sd-radio-group__radio[data-size="large"] {
  --sd-radio-group-radio-gap-current: var(--sd-radio-group-radio-gap-large);
  --sd-radio-group-radio-padding-block-current: var(--sd-radio-group-radio-padding-block-large);
  --sd-radio-group-radio-state-layer-spread-current: var(--sd-radio-group-radio-state-layer-spread-large);
  --sd-radio-group-radio-indicator-size-current: var(--sd-radio-group-radio-indicator-size-large);
  --sd-radio-group-radio-dot-size-current: var(--sd-radio-group-radio-dot-size-large);
}

/* RadioButton (<label>): the clickable interactive region — indicator + label, with the padded,
   rounded hover/press area (NavItem-style ghost overlay, ADR-0009). Rest transparent. */
.sd-radio-group__radio-button {
  --sd-radio-group-radio-indicator-background-current: var(--sd-radio-group-radio-indicator-background);
  --sd-radio-group-radio-indicator-border-current: var(--sd-radio-group-radio-indicator-border);
  --sd-radio-group-radio-dot-scale-current: 0;
  /* the hover/pressed state-layer + focus ring hug the INDICATOR (compact circle), never the
     label. Set per state here; read on the indicator's ::before below (§5, combinator-free). */
  --sd-radio-group-radio-state-layer-current: transparent;
  --sd-radio-group-radio-ring-current: 0 0 0 0 transparent;
  --sd-radio-group-radio-ring-outline-current: none;

  display: inline-flex;
  /* top-align the indicator to a wrapping label's FIRST line (see Checkbox). */
  align-items: flex-start;
  gap: var(--sd-radio-group-radio-gap-current);
  padding-block: var(--sd-radio-group-radio-padding-block-current);
  padding-inline: var(--sd-radio-group-radio-padding-inline);
  border-radius: var(--sd-radio-group-radio-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-radio-group-radio-background);
  color: var(--sd-radio-group-radio-label-foreground);
  cursor: pointer;
  user-select: none;
  position: relative;
  outline: none;
}
/* filled — the whole row is a box on the neutral fill. The border keeps its width at rest,
   transparent, so the chosen box colours its edge without moving its content. */
.sd-radio-group__radio-button[data-variant="filled"] {
  flex: 1;
  padding: var(--sd-radio-group-radio-padding-filled);
  border: var(--sd-radio-group-radio-border-width) solid var(--sd-radio-group-radio-border-filled);
  border-radius: var(--sd-radio-group-radio-radius-filled);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-radio-group-radio-background-filled);
}
.sd-radio-group__radio-button[data-variant="filled"][data-selected] {
  border-color: var(--sd-radio-group-radio-border-filled-selected);
  background: var(--sd-radio-group-radio-background-filled-selected);
}
.sd-radio-group__radio-button[data-hovered] {
  --sd-radio-group-radio-indicator-border-current: var(--sd-radio-group-radio-indicator-border-hover);
  --sd-radio-group-radio-state-layer-current: var(--sd-state-hover);
}
.sd-radio-group__radio-button[data-pressed] {
  --sd-radio-group-radio-state-layer-current: var(--sd-state-pressed);
}
.sd-radio-group__radio-button[data-selected] {
  --sd-radio-group-radio-indicator-background-current: var(--sd-radio-group-radio-indicator-background-selected);
  --sd-radio-group-radio-indicator-border-current: var(--sd-radio-group-radio-indicator-border-selected);
  --sd-radio-group-radio-dot-scale-current: 1;
}
.sd-radio-group__radio-button[data-invalid] {
  --sd-radio-group-radio-indicator-border-current: var(--sd-radio-group-radio-indicator-border-invalid);
}
.sd-radio-group__radio-button[data-disabled] {
  cursor: not-allowed;
}
.sd-radio-group__radio-button[data-readonly] {
  /* read-only: still focusable/valid, just not selectable — signal via cursor. */
  cursor: default;
}
.sd-radio-group__radio-button[data-focus-visible] {
  --sd-radio-group-radio-ring-current: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  --sd-radio-group-radio-ring-outline-current: var(--sd-state-focus-ring-width) solid transparent;
}

.sd-radio-group__radio-indicator {
  position: relative;
  display: inline-flex;
  flex: 0 0 auto;
  /* centre the indicator on the label's first line: (the label's own line box − size) / 2. `1lh`
     reads the role class on the <label>, so it holds at every size, brand and usage context; the
     `1.5rem` it replaces was the default brand's medium line box only (see Checkbox). */
  margin-block-start: calc((1lh - var(--sd-radio-group-radio-indicator-size-current)) / 2);
  align-items: center;
  justify-content: center;
  width: var(--sd-radio-group-radio-indicator-size-current);
  height: var(--sd-radio-group-radio-indicator-size-current);
  background: var(--sd-radio-group-radio-indicator-background-current);
  border: var(--sd-radio-group-radio-indicator-border-width) solid var(--sd-radio-group-radio-indicator-border-current);
  border-radius: var(--sd-radio-group-radio-indicator-radius);
  corner-shape: round;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    border-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
/* Interaction state-layer + focus ring as a compact circle hugging the indicator (ADR-0009),
   extending `state-layer-spread` beyond it on every side. Translucent hover/pressed tint reads as
   a halo around the circle; the label is never covered. At ~32px it also satisfies the WCAG 2.5.8
   (24px) target the old transparent hit-area provided (matches Checkbox). */
.sd-radio-group__radio-indicator::before {
  content: "";
  position: absolute;
  inset: calc(-1 * var(--sd-radio-group-radio-state-layer-spread-current));
  border-radius: var(--sd-radio-group-radio-indicator-radius);
  corner-shape: round;
  background: var(--sd-radio-group-radio-state-layer-current);
  box-shadow: var(--sd-radio-group-radio-ring-current);
  outline: var(--sd-radio-group-radio-ring-outline-current);
  pointer-events: none;
  transition:
    background-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-radio-group__radio-indicator::after {
  content: "";
  width: var(--sd-radio-group-radio-dot-size-current);
  height: var(--sd-radio-group-radio-dot-size-current);
  background: var(--sd-radio-group-radio-dot-background);
  border-radius: var(--sd-radio-group-radio-dot-radius);
  corner-shape: round;
  transform: scale(var(--sd-radio-group-radio-dot-scale-current));
  transition: transform var(--sd-duration-moderate) var(--sd-easing-standard);
}

.sd-radio-group__radio-label {
  color: var(--sd-radio-group-radio-label-foreground);
}

@media (prefers-reduced-motion: reduce) {
  .sd-radio-group__radio-indicator::after {
    transition: none;
  }
}
